    #[test]
    fn spec_k_policy_maps_placement_and_concurrency_to_plain() {
        let pp2 = resolve_spec_gate_thresholds(true, None, None);
        assert_eq!(
            choose_spec_k(None, true, pp2, 1, 28, 0, false),
            SpecKDecision {
                k: 0,
                reason: SpecKReason::Placement
            },
        );

        let single = resolve_spec_gate_thresholds(false, None, None);
        assert_eq!(
            choose_spec_k(None, true, single, 3, 28, 0, false),
            SpecKDecision {
                k: 0,
                reason: SpecKReason::Concurrency
            },
        );

        // An explicit PP-2 threshold override restores the measured gate semantics:
        // c=1 may speculate; the next arrival is K=0.
        let pp2_c1 = resolve_spec_gate_thresholds(true, Some(1), Some(2));
        assert_eq!(
            choose_spec_k(None, true, pp2_c1, 1, 28, 0, false),
            SpecKDecision {
                k: SPEC_K_COLD_SHORT,
                reason: SpecKReason::ColdShort
            },
        );
        assert_eq!(
            choose_spec_k(None, true, pp2_c1, 2, 28, 0, false),
            SpecKDecision {
                k: 0,
                reason: SpecKReason::Concurrency
            },
        );
    }

    #[test]
    fn spec_k_prompt_cache_table_has_exact_boundaries() {
        assert_eq!(
            (
                SPEC_K_COLD_SHORT,
                SPEC_K_COLD_LONG,
                SPEC_K_CACHED_LONG,
                SPEC_K_CACHED_LONG_TRIM,
            ),
            (3, 3, 2, 5),
        );
        // trim-keyed cached-long: a rank-trimmed head re-prices the cached-long depth
        // (research/orndecode-20260822 — K=5 350.8 tok/s vs ~273 at k=2 on ornith15).
        assert_eq!(
            choose_spec_k(
                None,
                true,
                resolve_spec_gate_thresholds(false, None, None),
                1,
                SPEC_K_LONG_PROMPT_MIN,
                SPEC_K_LONG_CACHE_MIN,
                true,
            ),
            SpecKDecision {
                k: SPEC_K_CACHED_LONG_TRIM,
                reason: SpecKReason::CachedLong
            },
        );
        let single = resolve_spec_gate_thresholds(false, None, None);
        assert_eq!(
            choose_spec_k(
                None,
                true,
                single,
                1,
                SPEC_K_LONG_PROMPT_MIN - 1,
                9999,
                false
            ),
            SpecKDecision {
                k: SPEC_K_COLD_SHORT,
                reason: SpecKReason::ColdShort
            },
        );
        assert_eq!(
            choose_spec_k(
                None,
                true,
                single,
                1,
                SPEC_K_LONG_PROMPT_MIN,
                SPEC_K_LONG_CACHE_MIN - 1,
                false,
            ),
            SpecKDecision {
                k: SPEC_K_COLD_LONG,
                reason: SpecKReason::ColdLong
            },
        );
        assert_eq!(
            choose_spec_k(
                None,
                true,
                single,
                1,
                SPEC_K_LONG_PROMPT_MIN,
                SPEC_K_LONG_CACHE_MIN,
                false,
            ),
            SpecKDecision {
                k: SPEC_K_CACHED_LONG,
                reason: SpecKReason::CachedLong
            },
        );
        // MEMRA_SPEC_GATE=0 retains its rollback meaning: placement/concurrency are
        // ignored, while the prompt/cache table remains active.
        assert_eq!(
            choose_spec_k(
                None,
                false,
                resolve_spec_gate_thresholds(true, None, None),
                8,
                SPEC_K_LONG_PROMPT_MIN,
                SPEC_K_LONG_CACHE_MIN,
                false
            ),
            SpecKDecision {
                k: SPEC_K_CACHED_LONG,
                reason: SpecKReason::CachedLong
            },
        );
    }

    /// GLM5 ROUTING GATE (lane/glm5-spec-routing, 2026-08-30): the serve-time route
    /// decision, exact over the class matrix — one green row per sampling regime, then
    /// every exclusion flipped alone must refuse (fail-closed reds, each named).
    #[test]
    fn glm5_route_class_matrix_is_exact() {
        use super::glm5_route_admits;
        // (capable, serve_spec, k, temp_ok, penalized, constrained, vision, cold, primeable)
        let green = |k| glm5_route_admits(true, true, k, true, false, false, false, true, true);
        assert!(
            green(3),
            "greedy/sampled cold unpenalized K>0 is the routed class"
        );
        assert!(green(1) && green(14), "every legal K routes");
        assert!(
            !glm5_route_admits(false, true, 3, true, false, false, false, true, true),
            "not capable (flag off / no MTP head / manifest blocked / ppN / sealed bundle \
             without a glm5-spec receipt) must refuse — the off-flag arm"
        );
        assert!(
            !glm5_route_admits(true, false, 3, true, false, false, false, true, true),
            "MEMRA_SERVE_SPEC=0 / vision / capture / pp-bounce (serve_spec) must refuse"
        );
        assert!(
            !glm5_route_admits(true, true, 0, true, false, false, false, true, true),
            "K=0 (operator pin 0 or the concurrency shed) must refuse"
        );
        assert!(
            !glm5_route_admits(true, true, 3, false, false, false, false, true, true),
            "neither greedy nor a real temperature must refuse"
        );
        assert!(
            !glm5_route_admits(true, true, 3, true, true, false, false, true, true),
            "penalties (greedy OR sampled) must refuse when the call site says they stay \
             plain (`glm5_penalty_plain`: the MEMRA_SPEC_PENALTY door is dark); silently \
             dropping them is the failure class"
        );
        assert!(
            !glm5_route_admits(true, true, 3, true, false, true, false, true, true),
            "constrained requests must refuse (grammar hooks live on the qwen program only)"
        );
        assert!(
            !glm5_route_admits(true, true, 3, true, false, false, true, true, true),
            "vision sessions must refuse (no embedding-overlay seam in the glm5 prime)"
        );
        assert!(
            !glm5_route_admits(true, true, 3, true, false, false, false, false, true),
            "a warm session that is NEITHER cold NOR the restored carrier must refuse — \
             the `cold_or_restored_carrier` param (lane/glm5-prefix-latent2): the \
             call site passes `glm5_cold || glm5_restored_carrier`, and the carrier proof \
             (rebuilt drafter KV + restored cache + non-empty seed, every other spec-state \
             term still cold) lives at the call site, not here"
        );
        assert!(
            !glm5_route_admits(true, true, 3, true, false, false, false, true, false),
            "a sub-primeable prompt (< 2 tokens) must refuse — the MTP plane warms on \
             (token[i+1], hidden[i]) pairs and generate_spec_glm5 refuses at prime time, \
             which is PAST the plain fallback; a one-word prompt serves plain, never a \
             500 (memra#9)"
        );
    }

    /// THE PENALTY DOOR (lane/spec-exclusions-20260902): the glm5 session seam carries a
    /// GREEDY request's penalties in (temp 0, pen_on), stays `None` for a pure greedy
    /// request (the byte-identical instrument route), and is `spec_sampling_for` for a
    /// sampled one — field for field.
    #[test]
    fn glm5_spec_sampling_seam_carries_greedy_penalties_and_nothing_else() {
        use super::{glm5_spec_sampling_for, spec_sampling_for};
        let greedy = Sampler::new(SamplerConfig::default());
        assert!(
            glm5_spec_sampling_for(&greedy).is_none(),
            "pure greedy stays the byte-contract route (None)"
        );
        let greedy_pen = Sampler::new(SamplerConfig {
            penalty_last_n: memra_engine::spec::PEN_WINDOW_MAX,
            penalty_present: 0.5,
            ..SamplerConfig::default()
        });
        let sp = glm5_spec_sampling_for(&greedy_pen).expect("greedy + penalties carries in");
        assert_eq!(
            sp.temp, 0.0,
            "temperature stays 0: the verify is still greedy"
        );
        assert!(sp.pen_on(), "the penalty state must be live on the seam");
        assert!(
            spec_sampling_for(&greedy_pen).is_none(),
            "the shared seam keeps its meaning: None at temperature 0"
        );
        let window_off = Sampler::new(SamplerConfig {
            penalty_last_n: 0,
            penalty_present: 0.5,
            ..SamplerConfig::default()
        });
        assert!(
            glm5_spec_sampling_for(&window_off).is_none(),
            "a coefficient with no window is penalties-absent (the host sampler applies \
             nothing either)"
        );
        let sampled = Sampler::new(SamplerConfig {
            temperature: 0.7,
            top_p: 0.9,
            penalty_last_n: memra_engine::spec::PEN_WINDOW_MAX,
            penalty_repeat: 1.1,
            seed: 7,
            ..SamplerConfig::default()
        });
        let a = glm5_spec_sampling_for(&sampled).expect("sampled");
        let b = spec_sampling_for(&sampled).expect("sampled");
        assert_eq!(
            format!("{a:?}"),
            format!("{b:?}"),
            "a sampled request must get the shared seam's config, field for field"
        );
    }

    /// WIRING (comment-stripped, live slice only): the penalty door composes into the ONE
    /// verdict both the carrier probe and the route decision read; the warm door lives in
    /// the probe's no-tail arm with its print-once line; the glm5 tick creates sessions
    /// through the glm5 seam on BOTH arms (cold and restored).
    #[test]
    fn spec_penalty_and_warm_doors_are_wired_in_comment_stripped_source() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let live = &code[..code.find("mod tests").expect("the test module exists")];
        let sq: String = live.split_whitespace().collect::<Vec<_>>().join(" ");
        // 1. ONE verdict, from the engine's door.
        assert!(
            sq.contains(
                "let glm5_penalty_plain = glm5_penalized && \
                 !memra_engine::glm_spec::glm5_spec_penalty_on();"
            ),
            "the penalized-plain verdict must AND the request shape with the engine door"
        );
        // 2. The carrier probe reads it (not the raw shape).
        let probe = sq
            .find("&& let Some(carrier) = reused.as_ref() && prefix_hit")
            .expect("the glm5 carrier probe exists");
        let probe_head = &sq[probe.saturating_sub(400)..probe];
        assert!(
            probe_head.contains("&& !glm5_penalty_plain"),
            "the carrier probe must exclude only penalized-PLAIN requests"
        );
        // 3. The route predicate and its reason read the same verdict.
        for call in ["glm5_route_admits(", "glm5_route_decline_reason("] {
            let at = sq
                .find(&format!("= {call}"))
                .unwrap_or_else(|| panic!("the {call} call exists"));
            assert!(
                sq[at..at + 400].contains("glm5_penalty_plain,"),
                "{call} must receive the penalized-plain verdict"
            );
        }
        // 4. The warm door: the no-tail arm re-arms a cold drafter, names its refusal, and
        //    announces once.
        assert!(
            sq.contains("memra_engine::glm_spec::glm5_spec_warm_on()"),
            "the warm door must be read at the probe"
        );
        assert!(
            sq.contains("memra_engine::dflash::DflashKv::new_cold_at("),
            "the warm arm must build the cold drafter through new_cold_at"
        );
        assert!(
            sq.contains("glm5_carrier_declined = Some(\"warm-cold-drafter-refused\");"),
            "a cold-drafter refusal must name itself on the route line"
        );
        assert!(
            live.split_whitespace()
                .collect::<String>()
                .contains("SPEC_WARM_ANNOUNCED.swap(true"),
            "the warm engagement line must be print-once"
        );
        // 5. Both session constructors on the tick go through the glm5 seam.
        let step = code
            .split("fn step_glm5_spec(")
            .nth(1)
            .expect("step_glm5_spec exists");
        let step_body = &step[..step.find("\nfn ").unwrap_or(step.len())];
        assert_eq!(
            step_body
                .matches("glm5_spec_sampling_for(&s.sampler)")
                .count(),
            2,
            "the cold and the restored arm must both carry penalties in through the glm5 seam"
        );
        assert!(
            !step_body.contains(" spec_sampling_for(&s.sampler)"),
            "no bare spec_sampling_for on the glm5 tick (it drops a greedy request's penalties)"
        );
    }

    /// THE memra#74 GATE: a FULL-COVER prefix hit (the repeated-prompt shape) must be an
    /// admissible spec carrier once the arm is armed, and must NAME itself when it is not.
    ///
    /// RED ARM: the predicate is new, so the red run was this body with the full-cover arm
    /// removed, i.e. the shipped pre-lane rule ("a full-cover hit is never a carrier")
    /// expressed in the new shape. The armed row below then fails with
    /// `left: Err("full-cover-hit"), right: Ok(())`, which IS the live defect: the drafter
    /// never engaged on a hit and decode ran at plain speed (30.8 vs 69.7 tok/s on the box,
    /// 2026-09-02). Banked in the PR body.
    #[test]
    fn glm5_full_cover_hit_is_an_admissible_carrier_and_always_names_itself() {
        use super::glm5_carrier_admits;
        // (prefix_restore_on, fullcover_on, suffix_len, has_boundary_logits)
        assert_eq!(
            glm5_carrier_admits(true, true, 0, true),
            Ok(()),
            "a full-cover hit with the arm armed and boundary logits present IS a carrier: \
             the whole point of memra#74; the restored state is a cold session's state at \
             the same boundary (trunk cache at fed.len(), drafter ctx KV at fed.len(), no \
             pending rows, anchor off the entry's boundary row)"
        );
        assert_eq!(
            glm5_carrier_admits(true, false, 0, true),
            Err("full-cover-hit"),
            "DISARMED is still the default posture (no GPU receipt yet), but it must NAME \
             itself so the route line can print reason=full-cover-hit instead of a bare \
             route=plain with cold=0 restored=0"
        );
        assert_eq!(
            glm5_carrier_admits(true, true, 0, false),
            Err("full-cover-hit-no-boundary-logits"),
            "armed but with no boundary row there is no anchor to start a round from: \
             refuse by name (the spec_restore_refusal full-cover rule)"
        );
        assert_eq!(
            glm5_carrier_admits(false, true, 0, true),
            Err("prefix-restore-off"),
            "without MEMRA_GLM5_SPEC_PREFIX no entry carries a drafter tail at all"
        );
        // The suffix-bearing arms are UNCHANGED by this lane.
        assert_eq!(
            glm5_carrier_admits(true, false, memra_engine::hybrid_forward::PRIME_MIN_T, true),
            Ok(()),
            "a suffix at or above the prime floor is the parent lane's carrier, and the \
             full-cover arm does not gate it"
        );
        assert_eq!(
            glm5_carrier_admits(
                true,
                true,
                memra_engine::hybrid_forward::PRIME_MIN_T - 1,
                true
            ),
            Err("suffix-below-prime-floor"),
            "a sub-floor suffix still keeps the plain hit (a tokenwise suffix inside a \
             prime program is the two-programs door the parent lane closed), and it, too, \
             says so on the route line"
        );
    }

    /// The route LINE and the route DECISION are one matrix, read out two ways (memra#74).
    /// `glm5_route_decline_reason` returns `None` exactly when `glm5_route_admits` is true,
    /// over every arm, so a future term added to one and forgotten in the other reds here
    /// instead of shipping a `route=plain reason=-` to an operator.
    #[test]
    fn the_route_reason_agrees_with_the_route() {
        use super::{glm5_route_admits, glm5_route_decline_reason};
        for capable in [false, true] {
            for serve_spec in [false, true] {
                for k in [0usize, 3] {
                    for temp_ok in [false, true] {
                        for penalized in [false, true] {
                            for constrained in [false, true] {
                                for vision in [false, true] {
                                    for carrier in [false, true] {
                                        for primeable in [false, true] {
                                            let admits = glm5_route_admits(
                                                capable,
                                                serve_spec,
                                                k,
                                                temp_ok,
                                                penalized,
                                                constrained,
                                                vision,
                                                carrier,
                                                primeable,
                                            );
                                            let reason = glm5_route_decline_reason(
                                                capable,
                                                serve_spec,
                                                k,
                                                temp_ok,
                                                penalized,
                                                constrained,
                                                vision,
                                                carrier,
                                                primeable,
                                                None,
                                            );
                                            assert_eq!(
                                                admits,
                                                reason.is_none(),
                                                "route/reason disagree at (capable {capable}, \
                                                 serve_spec {serve_spec}, k {k}, temp_ok \
                                                 {temp_ok}, penalized {penalized}, constrained \
                                                 {constrained}, vision {vision}, carrier \
                                                 {carrier}, primeable {primeable})"
                                            );
                                            assert_ne!(
                                                reason,
                                                Some(""),
                                                "a decline reason is never empty"
                                            );
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        // The memra#74 shape end to end: capable, serving, K>0, sampled, unpenalized, a
        // 67-token prompt, declined ONLY because the full-cover hit is not a carrier. The
        // route line must carry the carrier's own token, not the generic warm-session one.
        assert_eq!(
            glm5_route_decline_reason(
                true,
                true,
                3,
                true,
                false,
                false,
                false,
                false,
                true,
                Some("full-cover-hit"),
            ),
            Some("full-cover-hit"),
            "the live box's line read `route=plain ... cold=0 restored=0` with no reason; \
             it must now read reason=full-cover-hit"
        );
        assert_eq!(
            glm5_route_decline_reason(true, true, 3, true, false, false, false, false, true, None,),
            Some("warm-session-no-carrier"),
            "a warm session that was never a prefix hit still names itself"
        );
    }

    /// ROUTE POLICY CAP (lane/spec-route-depth-20260902): the parse and the predicate,
    /// pure. Unset/0/junk = unlimited; the cap is a strict "longer than".
    #[test]
    fn spec_max_prompt_cap_parses_and_caps_strictly_above() {
        use super::{glm5_route_prompt_capped, parse_spec_max_prompt};
        assert_eq!(parse_spec_max_prompt(None), None);
        assert_eq!(parse_spec_max_prompt(Some("")), None);
        assert_eq!(parse_spec_max_prompt(Some("0")), None);
        assert_eq!(parse_spec_max_prompt(Some("x")), None);
        assert_eq!(parse_spec_max_prompt(Some(" 131072 ")), Some(131072));
        assert!(!glm5_route_prompt_capped(66, None), "unset = unlimited");
        assert!(
            !glm5_route_prompt_capped(131072, Some(131072)),
            "at the cap routes spec"
        );
        assert!(
            glm5_route_prompt_capped(131073, Some(131072)),
            "one past the cap is plain"
        );
        assert!(glm5_route_prompt_capped(256_756, Some(131072)));
    }

    /// WIRING (comment-stripped): the cap composes AFTER the correctness predicate, the
    /// route reason names it, and the print-once line reads the same door.
    #[test]
    fn spec_max_prompt_cap_is_wired_after_the_route_predicate() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let live = &code[..code.find("mod tests").expect("the test module exists")];
        let sq: String = live.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            sq.contains(
                "let glm5_capped = glm5_capable && glm5_route_prompt_capped(prompt.len(), \
                 spec_max_prompt());"
            ),
            "the cap must be computed from the door at admission"
        );
        assert!(
            sq.contains("let glm5_on = glm5_admits && !glm5_capped;"),
            "the route decision must AND the cap after the correctness predicate"
        );
        assert!(
            sq.contains(".or_else(|| glm5_capped.then_some(\"prompt-above-spec-max\"));"),
            "a capped request must name the cap as its route reason"
        );
        assert!(
            sq.contains("SPEC_MAX_PROMPT_ANNOUNCED.swap(true"),
            "the engagement line must be print-once"
        );
    }

    /// The K+1 <= 15 hard bound (the shexp decode-exact knee at t=16): only an operator
    /// pin can reach the clamp; every automatic policy depth passes through untouched.
    #[test]
    fn glm5_spec_k_clamp_holds_the_verify_knee() {
        use super::glm5_clamp_spec_k;
        assert_eq!(glm5_clamp_spec_k(14), 14, "K=14 is the last legal depth");
        assert_eq!(
            glm5_clamp_spec_k(15),
            14,
            "K+1 = 16 crosses the knee — clamped"
        );
        assert_eq!(
            glm5_clamp_spec_k(64),
            14,
            "any operator pin clamps to the knee"
        );
        for policy_k in [
            SPEC_K_COLD_SHORT,
            SPEC_K_COLD_LONG,
            SPEC_K_CACHED_LONG,
            SPEC_K_CACHED_LONG_TRIM,
        ] {
            assert_eq!(
                glm5_clamp_spec_k(policy_k),
                policy_k,
                "the shared policy table's automatic depths sit inside the knee"
            );
        }
    }

    /// WIRING GATE (anchored on invocations in comment-stripped source, never prose —
    /// the wiring-assertions-match-prose law): the glm5 route's seams are LIVE code.
    #[test]
    fn glm5_route_wiring_is_live_in_comment_stripped_source() {
        let src = include_str!("worker.rs");
        let code: String = src
            .lines()
            .map(|l| l.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        // 1. The tick dispatch keys on the session flag and calls the glm5 step — BEFORE
        //    the gemma arm and the plain fallback (a glm5 session reaching either is the
        //    empty-context garbage class).
        let dispatch = code
            .find("step_dspark_spec(&engine, &loaded, &mut dspark_drafts, &mut active[i])")
            .expect("the spec dispatch exists");
        let window = &code[dispatch..dispatch + 700];
        let glm5_arm = window
            .find("else if active[i].glm5_on {")
            .expect("the glm5 dispatch arm keys on glm5_on");
        let glm5_call = window
            .find("step_glm5_spec(&engine, &loaded, &mut active[i])")
            .expect("the glm5 dispatch arm invokes step_glm5_spec");
        let gemma_arm = window
            .find("else if active[i].gspec_k > 0 {")
            .expect("the gemma arm still exists");
        assert!(glm5_arm < glm5_call && glm5_call < gemma_arm);
        // EVERY assertion below anchors on the LIVE slice, never on `code` (which contains
        // this test's own string literals and would satisfy `contains` with itself — the
        // self-match trap the wiring-assertions law names; three of the round-1 assertions
        // were born with it).
        let live_pre_tests = &code[..code.find("mod tests").expect("the test module exists")];
        // 2. The phase-(a) scheduler filter includes glm5 sessions, or they never burst.
        let filter = live_pre_tests
            .find("active[i].spec.is_some()")
            .expect("the phase-a filter exists");
        assert!(
            live_pre_tests[filter..filter + 300].contains("|| active[i].glm5_on"),
            "the phase-a spec filter must include glm5_on sessions"
        );
        // 3. Admission computes the route through the PURE predicate and the K clamp.
        assert!(
            live_pre_tests.contains("let glm5_admits = glm5_route_admits("),
            "the route predicate must be computed via glm5_route_admits"
        );
        assert!(
            live_pre_tests.contains("let glm5_on = glm5_admits && !glm5_capped;"),
            "glm5_on must be the predicate ANDed with the MEMRA_SPEC_MAX_PROMPT cap \
             (lane/spec-route-depth-20260902)"
        );
        assert!(
            live_pre_tests.contains("glm5_clamp_spec_k(decision.k)"),
            "the chosen K must pass the knee clamp"
        );
        // 3b. THE ROUTE LINE CARRIES A REASON (memra#74). The receipt an operator reads must
        //     never again say `route=plain` with nothing but `cold=0 restored=0` to explain
        //     it: the reason token comes from the same matrix as the decision, and the
        //     carrier's own decline token is threaded into it.
        let route_line = live_pre_tests
            .find("[glm5-spec] route={} K={glm5_k}")
            .expect("the glm5 admission receipt exists");
        assert!(
            live_pre_tests[route_line..route_line + 400].contains("reason={}"),
            "the glm5 route receipt must carry a reason token"
        );
        assert!(
            live_pre_tests.contains("let plain_reason = glm5_route_decline_reason("),
            "the reason must come from the pure predicate, never be re-derived at the log site"
        );
        assert!(
            live_pre_tests.contains("glm5_carrier_declined,"),
            "the carrier's own decline token must be threaded into the route reason"
        );
        assert!(
            live_pre_tests.contains("let admit = glm5_carrier_admits("),
            "the prefix-hit carrier probe must go through the pure predicate"
        );
        // 4. The session-owned-cache arm: admission must not allocate a plain cache under
        //    a glm5 route — EXCEPT the restored carrier (lane/glm5-prefix-latent2), which
        //    keeps the restored cache for the first spec tick to consume. Anchored on the
        //    PRE-TEST slice: the old form of this assertion matched its own string literal
        //    (the self-match trap the wiring-assertions law names).
        assert!(
            live_pre_tests.contains(
                "let cache = if dspark_on || (glm5_on && glm5_prefix_restored_dkv.is_none()) {"
            ),
            "the cache literal must carry the glm5 no-alloc arm with the restored-carrier exception"
        );
        assert!(
            live_pre_tests.contains("glm5_restored_dkv: glm5_prefix_restored_dkv,"),
            "the session literal must carry the restored drafter KV"
        );
        assert!(
            live_pre_tests.contains("glm5_spec_session_from_restored("),
            "the first spec tick must consume the restored carrier via from_restored"
        );
        assert!(
            live_pre_tests.contains("drain_glm5_prefix_capture(&engine, &mut px, &mut hpx, s);"),
            "the retire-adjacent sweep must drain glm5 boundary captures"
        );
        // 5. The per-request engagement receipt is an INVOCATION inside step_glm5_spec
        //    (the deploy gate greps the server log for it; never-serve-greedy law).
        let step = code
            .split("fn step_glm5_spec(")
            .nth(1)
            .expect("step_glm5_spec exists");
        let step_body = &step[..step.find("\nfn ").unwrap_or(step.len())];
        assert!(
            step_body.contains("\"[glm5-acc] ctx={} burst={}/{} cum={}/{}={:.3} trim_rounds={}\""),
            "the [glm5-acc] engagement line must be emitted by step_glm5_spec"
        );
        assert!(
            step_body.contains("glm5_spec_session_burst(engine, sess, burst_target, k,"),
            "step_glm5_spec must drive the engine session burst"
        );
        assert!(
            step_body.contains("emit_spec_token_events("),
            "glm5 bursts must emit through the shared one-event-per-public-id machinery"
        );
        // 5b. The FIRST-TOKEN EAGER door (lane/b200-spec-ttft-20260902): the door read
        //     selects the streamed burst twin, whose hook emits through the SAME machinery
        //     (both arms are invocations; the door-off arm keeps the literal above).
        assert!(
            step_body.contains("let eager_first_token = spec_first_token_eager_on();"),
            "the eager door must be read per burst inside step_glm5_spec"
        );
        assert!(
            step_body.contains("lm.model.glm5_spec_session_burst_streamed("),
            "the eager arm must drive the streamed burst twin"
        );
        assert!(
            step_body.matches("emit_spec_token_events(").count() >= 2,
            "both the round-cadence hook and the burst-cadence arm must emit through \
             emit_spec_token_events"
        );
        // 6. The capability predicate carries the flag, the manifest, the sealed-bundle
        //    surface and the ppN refusal — each an invocation, not a comment.
        let cap = code
            .split("fn glm5_spec_capable(")
            .nth(1)
            .expect("glm5_spec_capable exists");
        let cap_body = &cap[..cap.find("\nfn ").unwrap_or(cap.len())];
        for anchor in [
            "glm5_spec_on()",
            "RewriteSurface::Glm5Spec",
            "GLM5_SPEC",
            "pp_cuts(",
            ".speculative",
            // lane/glm5-ppn-verify: sharded placements admit ONLY through the gated-set
            // predicate AND a qualified pipeline rewrite — both as invocations.
            "glm5_sharded_placement_admits(",
            "RewriteSurface::Pipeline",
        ] {
            assert!(
                cap_body.contains(anchor),
                "glm5_spec_capable must consult {anchor}"
            );
        }
    }

    /// The sharded-placement matrix (lane/glm5-ppn-verify): stages 2 and 3 are the gated
    /// set (`glm5-spec-ppn-gate`); everything else sharded refuses by name, and a step
    /// TP/EP composition refuses at ANY stage count.
    #[test]
    fn glm5_sharded_placement_matrix_is_exact() {
        use super::glm5_sharded_placement_admits;
        assert!(
            glm5_sharded_placement_admits(2, None, None),
            "stages=2 is gated (SPLITS=24, the 2-card shape)"
        );
        assert!(
            glm5_sharded_placement_admits(3, None, None),
            "stages=3 is gated (SPLITS=15,30, the 3-card serving shape)"
        );
        assert!(
            !glm5_sharded_placement_admits(4, None, None),
            "stages=4 has no gate receipt and must refuse"
        );
        assert!(
            !glm5_sharded_placement_admits(1, None, None),
            "a one-stage fence cannot reach here (pp_cuts returns >= 2 stages) — refuse \
             rather than trust the impossible"
        );
        assert!(
            !glm5_sharded_placement_admits(2, Some("2"), None)
                && !glm5_sharded_placement_admits(3, None, Some("2")),
            "a step-TP/EP composition has never been co-gated with the glm5 walk"
        );
        assert!(
            glm5_sharded_placement_admits(2, Some("0"), Some("")),
            "an explicit off/empty TP value is not a TP placement"
        );
    }

    /// The plain step's glm5 refusal fires BEFORE any model work (the dspark
    /// dispatch-disagreement guard, extended): a session holding a glm5 spec session must
    /// never be stepped plain over its absent s.cache.
