    // ---- drafter attachment: the loud-failure semantics (lane/step-draft, 2026-08-07) ----
    //
    // These pin the class of bug that NO gate in this repo could catch: a step35 model served
    // without its external MTP drafter runs plain decode and produces CORRECT output, so
    // kernel-check is model-free, run-gen argmax MATCHes, and run-spec is never even reached.
    // Only a log line can flag it, so the log line is what gets tested.

    #[test]
    fn step35_without_drafter_warns_and_names_the_attach_spelling() {
        let v = draft_verdict(false, true);
        assert_eq!(v, DraftVerdict::NoDrafterExternalMtpArch);
        let msg = draft_verdict_message(&v, "step", "/m/Step-3.7-flash-IQ4_XS-00001-of-00003.gguf")
            .expect("a step35 model with no drafter MUST produce a line");
        // The defect is silence, so the line has to be findable and actionable.
        assert!(msg.contains("no MTP drafter attached"), "{msg}");
        assert!(msg.contains("plain decode"), "{msg}");
        // ACTIONABLE: the exact attach spelling, not just a complaint.
        assert!(msg.contains("MEMRA_MODELS"), "{msg}");
        assert!(
            msg.contains("+/path/to/"),
            "the '+draft' convention must be spelled: {msg}"
        );
        // And it must not read as a defect in the artifact — nextn=0 is CORRECT here.
        assert!(msg.contains("SEPARATE GGUF"), "{msg}");
        assert!(msg.contains("does NOT mean"), "{msg}");
    }

    #[test]
    fn attached_drafter_is_quiet_and_so_is_a_non_step35_model_without_one() {
        // Attached: nothing to warn about; spec_eligible arbitrates per request from here.
        // (#87 CLOSED 2026-08-08: a drafter over sharded cross-device PP-2 used to refuse
        // here — the ppN reverse-publication fences made the regime serve, receipts
        // research/pp2spec-crash-20260807/. Attached is now unconditional.)
        let v = draft_verdict(true, true);
        assert_eq!(v, DraftVerdict::Attached);
        assert!(draft_verdict_message(&v, "step", "/m.gguf").is_none());

        // A non-step35 model with no head: `nextn=0` there genuinely means no head, and the
        // existing load line already says the layer count. Warning would be noise on every
        // plain model the server has ever hosted — which is how a real warning gets ignored.
        let v = draft_verdict(false, false);
        assert_eq!(v, DraftVerdict::NoDrafterQuiet);
        assert!(draft_verdict_message(&v, "q27", "/m.gguf").is_none());
    }

    // (#87's refusal tests — `spec_over_sharded_pp_refuses_and_points_at_87`,
    // `the_quarantine_binds_only_where_all_three_conditions_hold`, and
    // `the_87_refusal_lands_before_the_load_when_a_draft_was_attached` — retired with the
    // quarantine itself, 2026-08-08. The regime they refused now serves: root cause was the
    // ppN reverse-publication hole, fixed by `PpNRt::fence_stages_behind`; crash gate
    // 212/212 at c=2..8, run-spec K=1..8 PASS. research/pp2spec-crash-20260807/.)

    /// Device-free PrefixEntry (empty kv/conv/ssm planes) — the namespace-visibility laws
    /// under test live entirely in the host-side key/toks matching.
    fn entry(pool_key: &PoolKey, toks: Vec<u32>) -> PrefixEntry {
        PrefixEntry {
            layout_version: PREFIX_ENTRY_LAYOUT_VERSION,
            dspark_draft: None,
            pool_key: pool_key.clone(),
            toks,
            kv: Vec::new(),
            conv: Vec::new(),
            ssm: Vec::new(),
            latent: Vec::new(),
            pos: 0,
            last_logits: vec![0.0],
            draft: None,
            last_h: Vec::new(),
            bytes: 1,
            last_use: std::time::Instant::now(),
            id: 0,
            segment: PrefixSegment::Probation,
            pins: 0,
        }
    }

    fn key(ns: &str) -> PoolKey {
        ("m".to_string(), ns.to_string())
    }

    fn toks(n: usize) -> Vec<u32> {
        (0..n as u32).collect()
    }

    /// A cache carrying a latent (MLA/DSA) plane must never be snapshotted into a PrefixEntry
    /// that has no state for that plane, or a "whole-entry" restore returns a session whose
    /// full-attention history is EMPTY while `cached_tokens` reports the whole prompt.
    /// lane/glm5-prefix-latent (2026-08-30): with `MEMRA_PREFIX_LATENT` OFF (the default) every
    /// arm is byte-for-byte the parent lane's guard; with it ON the capture proceeds (the entry
    /// then CARRIES the planes) and the restore admits ONLY carrying entries. Ordinary kv/recur
    /// models are untouched in every arm.
    #[test]
    fn a_latent_bearing_cache_is_refused_by_the_prefix_capture() {
        const GUARD: &str = "latent (MLA/DSA) KV planes are not carried by prefix entries";
        assert_eq!(super::unsupported_prefix_state_plane(true), Some(GUARD));
        assert_eq!(super::unsupported_prefix_state_plane(false), None);

        // Capture side. Flag off: the parent lane's refusal, string-identical (the box
        // flag-off arm greps this exact line). Flag on: capture proceeds and carries.
        assert_eq!(super::unsupported_prefix_capture(true, false), Some(GUARD));
        assert_eq!(super::unsupported_prefix_capture(true, true), None);
        assert_eq!(super::unsupported_prefix_capture(false, false), None);
        assert_eq!(super::unsupported_prefix_capture(false, true), None);
    }

    /// Restore side of the same guard: the admit is scoped to (flag ON) x (entry carries
    /// latent planes). An entry minted before the flip, or by the spec-boundary publisher,
    /// refuses exactly as under the parent lane's guard; flipping the flag OFF is the
    /// documented rollback seam and must refuse even carrying entries.
    #[test]
    fn the_restore_guard_admits_only_carrying_entries_and_only_under_the_flag() {
        const GUARD: &str = "latent (MLA/DSA) KV planes are not carried by prefix entries";
        // Non-latent cache: every entry class is unaffected in every flag state.
        for flag in [false, true] {
            for carries in [false, true] {
                assert_eq!(
                    super::unsupported_prefix_restore(false, flag, carries),
                    None
                );
            }
        }
        // Latent cache, flag off: the parent guard, regardless of what the entry carries
        // (rollback seam: unsetting the flag refuses carrying entries wholesale).
        assert_eq!(
            super::unsupported_prefix_restore(true, false, false),
            Some(GUARD)
        );
        assert_eq!(
            super::unsupported_prefix_restore(true, false, true),
            Some(GUARD)
        );
        // Latent cache, flag on: the admit exists ONLY for carrying entries.
        assert_eq!(super::unsupported_prefix_restore(true, true, true), None);
        assert_eq!(
            super::unsupported_prefix_restore(true, true, false),
            Some(
                "entry does not carry the latent (MLA/DSA) planes this cache requires \
                 (minted before or without latent capture)"
            ),
        );
    }

    /// Whole-entry only for latent-bearing entries, in its own right: an all-MLA pack has
    /// `entry_has_recurrent == false`, so without the latent arm an armed
    /// MEMRA_PREFIX_PARTIAL_RESTORE would slice latent rows mid-entry while the index tail
    /// ring for that interior boundary is unrecoverable.
    #[test]
    fn a_latent_entry_refuses_a_mid_entry_split_even_without_recurrent_state() {
        use super::{PartialPrefixDecision, partial_prefix_decision};
        // Mid-entry split on a latent-only entry: refused by the latent arm.
        assert_eq!(
            partial_prefix_decision(false, true, false, 100, 200, 300),
            PartialPrefixDecision::RefuseLatentMidEntry,
        );
        // The split AT the endpoint is not a mid-entry split; the suffix primes ahead.
        assert_eq!(
            partial_prefix_decision(false, true, false, 200, 200, 300),
            PartialPrefixDecision::Restore,
        );
        // The recurrent arm keeps precedence for hybrid entries (glm5: both are true).
        assert_eq!(
            partial_prefix_decision(true, true, false, 100, 200, 300),
            PartialPrefixDecision::RefuseRecurrentMidEntry,
        );
        // Non-latent entries decide exactly as before.
        assert_eq!(
            partial_prefix_decision(false, false, false, 100, 200, 300),
            PartialPrefixDecision::Restore,
        );
    }

    #[test]
    fn dspark_exact_transition_touch_promotes_without_cached_token_credit() {
        let k = key("");
        let prompt = toks(super::PREFIX_CACHE_MIN_TOKENS);
        let mut px = PrefixCache::default();
        px.insert_with_budget(&k, entry(&k, prompt.clone()), "dspark-test", 8);
        assert_eq!(px.entries[&k][0].segment, PrefixSegment::Probation);
        let credits = (px.hits, px.misses, px.hit_tokens);

        assert!(px.touch_exact_without_credit(&k, &prompt));
        assert_eq!(px.entries[&k][0].segment, PrefixSegment::Protected);
        assert_eq!(
            (px.hits, px.misses, px.hit_tokens),
            credits,
            "DFlash rebuilt the prompt, so residency changes without cache credit",
        );

        let mut different = prompt;
        different[0] = u32::MAX;
        assert!(!px.touch_exact_without_credit(&k, &different));
    }

